// === Tab: main.js ===
/*
Interactive logos

jasonlabbe3d.com
twitter.com/russetPotato
*/

const SPIN_MULTIPLIER = 45;
const MIN_PARTICLE_COUNT = 200;
const MAX_PARTICLE_COUNT = 700;
const MIN_PARTICLE_SIZE = 12;
const MAX_PARTICLE_SIZE = 50;
const MIN_FORCE = 0.4;
const MAX_FORCE = 0.6;
const REPULSION_RADIUS = 100;
const REPULSION_STRENGTH = 0.25;
const IMG_RESIZED_WIDTH = 300;
const IMG_SCAN_STEPS = 2;

const DrawTypes = {
	Rect: 0,
	Ellipse: 1,
	Triangle: 2
};

var imgNames = ["facebook.png", "amazon.png", "twitter.png", "visa.png", "mcdonalds.png", "mastercard.png"];
var particles = [];
var indices = [];
var imgIndex = 0;
var drawType = 0;
var particleCount = 550;
var maxSize = 0;
var img;

function setup() {
	let canvas = createCanvas(windowWidth, windowHeight);
	canvas.canvas.oncontextmenu = () => false;
	loadImg(imgNames[0]);
}

function draw() {
	background(0);

	fill(255);
	noStroke();
	text(
		`
		** How to interact **
		Move mouse over to interact with it.

		** Controls **
		Left-click : Switch image
		Right-click: Show source image
		+ : Increase count
		- : Decrease count
		Space: Change particle type`, 
		50, 50);

	if (img == null) {
		return;
	}

	push();
	translate(width / 2 - img.width / 2, height / 2 - img.height / 2);

	fill(255);
	noStroke();

	rectMode(CENTER);

	particles.forEach(particle => {
		particle.move();

		push();
		translate(particle.pos.x, particle.pos.y);

		let spin = particle.vel.mag() * SPIN_MULTIPLIER;
		rotate(radians(particle.mapped_angle + spin));

		fill(particle.color);

		switch(drawType) {
			case DrawTypes.Ellipse:
				ellipse(0, 0, particle.size, particle.size);
				break;
			case DrawTypes.Rect:
				rect(0, 0, particle.size, particle.size);
				break;
			case DrawTypes.Triangle:
				triangle(
					particle.size * -0.5, particle.size * -0.5, 
					0, particle.size, 
					particle.size * 0.5, particle.size * -0.5);
		}

		pop();
	});

	rectMode(CORNER);

	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton == RIGHT) {
		image(img, 0, 0);
	}

	pop();
}

function keyPressed() {
	if (key == '+') {
		particleCount = min(particleCount + 50, MAX_PARTICLE_COUNT);
		spawnParticles();
	}

	if (key == '-') {
		particleCount = max(particleCount - 50, MIN_PARTICLE_COUNT);
		spawnParticles();
	}

	if (key == ' ') {
		nextDrawType();
	}
}

function mousePressed() {
	if (mouseButton == LEFT) {
		loadNextImg();
	}
}

// === Tab: particle.js ===
function Particle(_x, _y, _size, _color) {
	this.pos = new p5.Vector(img.width / 2, img.height / 2);
  this.vel = new p5.Vector(0, 0);
  this.acc = new p5.Vector(0, 0);
	this.target = new p5.Vector(_x, _y);
	this.size = _size;
	this.mapped_angle = map(_x, 0, img.width, -180, 180) + map(_y, 0, img.height, -180, 180);
	this.color = _color;
	this.maxForce = random(MIN_FORCE, MAX_FORCE);

	this.goToTarget = function() {
    let steer = new p5.Vector(this.target.x, this.target.y);

    let distance = dist(this.pos.x, this.pos.y, this.target.x, this.target.y);
		if (distance > 0.5) {
			let distThreshold = 20;
			steer.sub(this.pos);
			steer.normalize();
			steer.mult(map(min(distance, distThreshold), 0, distThreshold, 0, this.maxForce));
			this.acc.add(steer);
		}
	}

	this.avoidMouse = function() {
		let mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2 + img.width / 2;
		let my = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2 + img.height / 2;

 		let mouseDistance = dist(this.pos.x, this.pos.y, mx, my);

		if (mouseDistance < REPULSION_RADIUS) {
			let repulse = new p5.Vector(this.pos.x, this.pos.y);
			repulse.sub(mx, my);
			repulse.mult(map(mouseDistance, REPULSION_RADIUS, 0, 0, REPULSION_STRENGTH));
			this.acc.add(repulse);
		}
	}

	this.move = function() {
		this.goToTarget();

		this.avoidMouse();

    this.vel.mult(0.95);

    this.vel.add(this.acc);
    this.pos.add(this.vel);
    this.acc.mult(0);
	}
}

// === Tab: utils.js ===
function loadNextImg() {
	imgIndex++;
	if (imgIndex >= imgNames.length) {
		imgIndex = 0;
	}
	loadImg(imgNames[imgIndex]);
}

function loadImg(imgName) {
	loadImage(imgName, newImg => {
    img = newImg;
		img.loadPixels();
		img.resize(IMG_RESIZED_WIDTH, 0);
		spawnParticles();
  });
}

// Collects valid positions where a particle can spawn onto.
function setupImg() {
	indices = [];

	for (let x = 0; x < img.width; x+=IMG_SCAN_STEPS * 4) {
		for (let y = 0; y < img.height; y+=IMG_SCAN_STEPS * 4) {
			let index = (x + y * img.width) * 4;

			let a = img.pixels[index + 3];
			if (a > 10) {
				indices.push(index);
			}
		}
	}
}

function spawnParticles() {
	particles = [];

	setupImg();

	maxSize = map(
		particleCount, 
		MIN_PARTICLE_COUNT, MAX_PARTICLE_COUNT, 
		MAX_PARTICLE_SIZE, MIN_PARTICLE_SIZE);

	if (indices.length == 0) {
		return;
	}

	for (let i = 0; i < particleCount; i++) {
		let max_attempts = 20;
		let attempts = 0;
		let newParticle = null;

		// Pick a random position from the active image and attempt to spawn a valid particle.
		while (newParticle == null) {
			var index = indices[int(random(indices.length))];

			let x = (index / 4) % img.width;
			let y = (index / 4) / img.width;

			let r = img.pixels[index];
			let g = img.pixels[index + 1];
			let b = img.pixels[index + 2];
			var a = img.pixels[index + 3];

			if (particles.length > 0) {
				let smallestSize = null;

				for (let i = 0; i < particles.length; i++) {
					let otherParticle = particles[i];
					let d = dist(x, y, otherParticle.target.x, otherParticle.target.y);
					let newSize = (d - (otherParticle.size / 2)) * 2;

					if (smallestSize == null || newSize < smallestSize) {
						smallestSize = newSize;
					}
				}

				if (smallestSize > 0) {
					newParticle = new Particle(
						x, y, 
						min(smallestSize, maxSize) * 0.75, 
						color(r, g, b, a));
				}
			} else {
				newParticle = new Particle(
					x, y, 
					maxSize,
					color(r, g, b, a));
			}

			attempts += 1;
			if (attempts > max_attempts) {
				break;
			}
		}

		if (newParticle != null) {
			particles.push(newParticle);	
		}
	}
}

function nextDrawType() {
	drawType++;
	if (drawType >= Object.keys(DrawTypes).length) {
		drawType = 0;
	}
}

